<script setup lang="ts">
import {computed,ref,watch,onMounted,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import {useMeetingCreateFlow} from './useMeetingCreateFlow';import MeetingInfoDrawer from './MeetingInfoDrawer.vue';import MeetingInfoEditor from './MeetingInfoEditor.vue';import Icon from '../../shared/Icon.vue';import FuturePanels from './FuturePanels.vue';
const app=useApplication(),{session,recorder:r,recordingStore,create,uploadQueue:queue}=app,route=useRoute(),router=useRouter(),panels=ref<InstanceType<typeof FuturePanels>>();const infoEditorRef=ref<InstanceType<typeof MeetingInfoEditor>>();function closeInfo(){if(infoEditorRef.value?.cancel?.()??true)infoOpen.value=false;}
const infoOpen=ref(false),interruptDialog=ref<HTMLDialogElement>(),endDialog=ref<HTMLDialogElement>(),busy=ref(false),localError=ref<string|null>(null),endError=ref<string|null>(null),lastEnd=ref<'save'|'process'|null>(null),live=ref<HTMLElement>();
const actor=()=>session.current.value?.actor.enterpriseId??null,meeting=computed(()=>r.record.value?.meeting??null),active=computed(()=>r.phase.value==='RECORDING'),paused=computed(()=>r.phase.value==='PAUSED'),saving=computed(()=>busy.value||r.phase.value==='SAVING'||r.phase.value==='AUTHORIZING'),failed=computed(()=>r.phase.value==='ERROR'&&!!r.record.value?.parts.length),finished=computed(()=>r.record.value?.finished??false),parts=computed(()=>r.record.value?.parts??[]),savedParts=computed(()=>parts.value.filter(p=>p.bytes>0&&!['RECORDING','PAUSED','SAVING'].includes(p.state)));
const interrupted=computed(()=>!active.value&&!paused.value&&parts.value.length>0&&!finished.value),state=computed(()=>saving.value?'保存中':failed.value?'保存失败':active.value?'录音中':paused.value?'已暂停':finished.value?'录音已保存':interrupted.value?'本段已中断':'等待麦克风授权');const label=computed(()=>failed.value?'重试保存':active.value?'暂停录音':paused.value?'继续录音':parts.value.length?'开始下一段':'重新授权并开始');const transcriptStatus=computed(()=>active.value?'识别中':paused.value?'已暂停，内容保留':interrupted.value?'已中断，内容保留':'当前累计内容'),saveStatus=computed(()=>finished.value?'已保存至服务端':'未接入服务端保存');
function clock(ms:number){const t=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}
const flow=useMeetingCreateFlow(create,actor,async id=>{await r.attach(id);await router.replace('/recording/'+id);app.setMeetingScope(id);return router.currentRoute.value.path==='/recording/'+id;});
async function initialize(){const id=typeof route.params.id==='string'?route.params.id:null;if(!actor())return;if(id){await r.attach(id);app.setMeetingScope(id);return;}const existing=r.record.value;if(existing&&!existing.finished){await router.replace('/recording/'+existing.meeting);app.setMeetingScope(existing.meeting);return;}const latest=await recordingStore.latest(actor()!);if(latest){const old=await recordingStore.load(actor()!,latest);if(old&&!old.finished){await r.attach(latest);await router.replace('/recording/'+latest);app.setMeetingScope(latest);}}}
async function start(){if(busy.value||finished.value)return;busy.value=true;localError.value=null;try{await initialize();if(!r.record.value||r.record.value.finished){await flow.open();if(flow.error.value)throw flow.error.value;}if(!r.record.value)throw Error('会议创建结果尚未确认，请重试原请求');if(!active.value&&!paused.value)await r.start();}catch(cause){localError.value=cause instanceof Error?cause.message:'无法开始录音，请重试。';}finally{busy.value=false;}}
async function primary(){if(failed.value){try{await r.retry();localError.value=null;}catch{/* Original chunks remain in recorder memory. */}return;}if(active.value){r.pause();return;}if(paused.value){try{await r.resume();}catch(cause){localError.value=cause instanceof Error?cause.message:'无法继续录音。';}return;}await start();}
async function interrupt(){busy.value=true;localError.value=null;try{await r.interrupt();interruptDialog.value?.close();}catch(cause){localError.value=cause instanceof Error?cause.message:'本段保存失败，请重试。';}finally{busy.value=false;}}
function end(){if(active.value)r.pause();lastEnd.value=null;endError.value=null;endDialog.value?.showModal();}
async function finish(action:'save'|'process'){
 if(busy.value)return;busy.value=true;lastEnd.value=action;endError.value=null;try{
  const id=meeting.value;if(!id)throw Error('尚无录音可保存');if(r.phase.value==='ERROR')await r.retry();await r.end();const files=await r.files();app.setMeetingScope(id);if(!queue.ready.value)await queue.open();if(!queue.ready.value||queue.blocked.value)throw Error('原上传记录暂不可用，请重试保存');if(queue.importCommand.state.value!=='EMPTY'){action='process';lastEnd.value='process';}
  if(queue.items.value.some(item=>!files.some(file=>file.name===item.name&&file.size===item.size)))throw Error('会议已有其他导入文件，请保留原清单并核对后继续');
  if(queue.importCommand.state.value==='EMPTY')for(const file of files){const previous=queue.items.value.find(item=>item.name===file.name&&item.size===file.size);if(!previous)await queue.add([file]);else if(!previous.fileId)await queue.retry(previous.key,file);}
  if(queue.importCommand.state.value==='EMPTY'&&queue.items.value.some(item=>!item.fileId))throw Error(queue.items.value.find(item=>item.error)?.error??'录音文件上传尚未确认，请重试保存');
  if(action==='process'){if(queue.importCommand.state.value!=='ACKNOWLEDGED')await queue.submitImport();if(queue.importCommand.state.value!=='ACKNOWLEDGED')throw Error('原处理请求尚未确认，请重试保存');}
  await r.finish();endDialog.value?.close();await router.push(action==='process'?'/meeting/'+id+'/processing':'/meetings');
 }catch(cause){endError.value=cause instanceof Error?cause.message:'录音保存未完成，请重试保存。';}finally{busy.value=false;}
}
let initializing:Promise<void>|null=null;async function load(){if(initializing)return initializing;initializing=initialize();try{await initializing;}catch(cause){localError.value=cause instanceof Error?cause.message:'录音记录暂不可用，请重试。';}finally{initializing=null;}}
const stop=watch(()=>[actor(),route.params.id],()=>{if(actor())void load();},{immediate:true});onMounted(async()=>{if(!session.current.value)try{await session.refresh();}catch{/* Session copy explains login state. */}await load();if(route.query.start==='1'){await router.replace({path:route.path,query:{}});await start();}});onUnmounted(()=>{stop();flow.dispose();});
</script>
<template><div class="layout"><div class="main"><header class="topbar"><RouterLink to="/meetings" class="topbar-home"><Icon name="list"/> 我的会议</RouterLink><span class="topbar-crumb">/ 在线录音</span></header><main class="content"><div class="ac-page acr-page"><header class="page-head"><div><h1 class="page-title">在线录音</h1><div class="page-desc">在线录音并实时转写，站内切换不影响录音，可继续处理其他工作。请保持当前标签页打开，刷新、关闭标签页或退出浏览器将中断录音。</div></div><button class="btn ghost" type="button" @click="router.push('/meetings')">返回会议列表</button></header>
 <section class="card acr-record-card" aria-label="会议录音"><div class="acr-record-top"><div class="acr-record-symbol" :class="active?'is-recording':'is-paused'"><Icon name="mic" :size="30"/><span></span></div><div class="acr-record-time"><strong id="ac-record-clock">{{clock(r.partElapsed.value)}}</strong><span id="ac-record-status">第{{parts.at(-1)?.index??1}}段 · {{state}}</span><small class="muted">累计录音 <time id="ac-record-total">{{clock(r.elapsed.value)}}</time></small></div><div class="acr-record-controls"><button class="acr-icon-button" :aria-label="label" :title="label" :disabled="saving||finished||!session.current.value" @click="primary"><Icon :name="failed?'refresh':active?'pause':'play'" :size="20"/></button><span class="acr-interrupt-slot"><button v-if="active||paused||saving" class="btn sm ghost" :disabled="saving||failed" @click="interruptDialog?.showModal()">中断本段</button></span><button class="acr-icon-button acr-stop" aria-label="结束录音" title="结束录音" :disabled="saving||failed||finished||!parts.length" @click="end"><svg width="19" height="19" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="5" y="5" width="14" height="14" rx="2"/></svg></button></div></div>
 <div class="acr-record-save small muted">本地已保存 {{parts.reduce((n,p)=>n+p.chunks.length,0)}} 个音频分片 · 保存范围约至 {{clock(parts.reduce((n,p)=>n+p.savedElapsedMs,0))}} · {{saveStatus}}</div><div v-if="savedParts.length" class="acr-saved-parts" aria-label="已保存录音文件"><span class="acr-parts-caption">已保存录音 · {{savedParts.length}}个文件</span><div class="acr-saved-part-files"><div v-for="part in savedParts" :key="part.id" class="acr-saved-part"><Icon name="file" :size="12"/><span>第{{part.index}}段 · {{part.name}}</span><time>{{clock(part.elapsedMs)}}</time><small :title="part.incomplete?'仅保留可恢复范围，尾段可能缺失':''">{{part.state==='SYSTEM_INTERRUPTED'?'系统中断':part.state==='INTERRUPTED'?'中断保存':part.state==='SAVED'?'结束保存':'已保存'}}{{part.incomplete?' · 范围不完整':''}}</small></div></div></div>
 <div class="acr-record-feedback"><div v-if="localError||r.error.value" class="ac-error" role="alert">{{localError??r.error.value}}</div><div v-else-if="!active&&!paused&&parts.length&&!finished" class="small muted acr-interruption-note">本段已保存，可开始下一段。</div><div v-if="!parts.length" class="small muted acr-interruption-note">请允许麦克风权限并检查设备。<RouterLink to="/meetings" class="btn sm ghost">改为导入文件</RouterLink></div></div><div class="acr-subtle-tools"><button class="acr-tool" :disabled="!meeting" @click="infoOpen=true"><Icon name="edit" :size="14"/> 填写会议信息</button><span></span><button class="acr-tool" :disabled="!meeting" @click="panels?.open('materials')"><Icon name="file" :size="14"/> 添加背景资料</button></div></section>
 <section class="card acr-transcript-card"><div class="card-h"><div class="card-t">实时转写</div><span class="small muted">全部录音段 · {{transcriptStatus}} · 模拟识别</span><button class="acr-tool ml-a" @click="live?.scrollTo({top:live.scrollHeight,behavior:'smooth'})"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 4v14m-5-5 5 5 5-5M5 21h14"/></svg> 回到最新</button></div><div ref="live" class="ac-live-text acr-live-text"><div class="acr-live-empty"><Icon name="mic" :size="26"/><p>等待会议内容</p><span>全部录音段的实时转写将在此累计展示。</span></div></div><div class="acr-simulation-note">音频由浏览器真实录制并保存在本地；实时文字和AI处理为示例模拟，未接入真实识别及服务端保存。系统中断仅保留已落盘范围，未保存尾段可能缺失。</div></section>
 </div></main></div></div><MeetingInfoDrawer :open="infoOpen" :prevent-close="infoEditorRef?.closeBlocked??false" @close="closeInfo"><MeetingInfoEditor ref="infoEditorRef" v-if="infoOpen&&meeting&&app.infoScopeReady.value" :meeting-id="meeting" :eligible="!finished" @close="infoOpen=false"/></MeetingInfoDrawer><FuturePanels ref="panels"/>
 <dialog ref="interruptDialog" class="notice-dialog" aria-labelledby="record-interrupt-title"><h3 id="record-interrupt-title">中断本段录音</h3><p class="mt16">本段将保存为独立文件，继续录音将开启下一段。</p><p v-if="localError||r.error.value" role="alert">{{localError??r.error.value}}</p><div class="flex mt16"><button class="btn" :disabled="busy" @click="interruptDialog?.close()">取消</button><button class="btn primary" :disabled="busy" @click="interrupt">保存本段</button></div></dialog>
 <dialog ref="endDialog" class="notice-dialog" aria-labelledby="record-end-title"><h3 id="record-end-title">结束录音</h3><p class="mt16">本次会议共{{parts.length}}段录音，累计{{clock(r.elapsed.value)}}。保存后可稍后继续处理，也可立即开始处理。</p><p class="small muted mt12">所有录音段按顺序归属同一会议，无需重新上传。取消将返回当前暂停或中断状态，不自动恢复录音。</p><p v-if="endError" class="ac-error mt12" role="alert">{{endError}}</p><div class="flex mt16"><button class="btn" :disabled="busy" @click="endDialog?.close()">取消</button><button v-if="endError&&lastEnd" class="btn primary" :disabled="busy" @click="finish(lastEnd)">重试保存</button><button class="btn" :disabled="busy||!!endError" @click="finish('save')">保存</button><button class="btn primary" :disabled="busy||!!endError" @click="finish('process')">开始处理</button></div></dialog>
</template>
